/// Render the scanner's complete observable output for the corpus.
///
/// Uses only the scanner's public API — kind label, byte offset, redaction label
/// and the redacted text — so this function is compilable against any revision
/// and the report it produces is directly comparable across revisions.
fn render_report() -> String {
    let scanner = CredentialScanner::new();
    let mut out = String::new();
    for (name, text) in CORPUS {
        let result = scanner.scan(text);
        out.push_str(&format!("## {name}\n"));
        out.push_str(&format!("findings: {}\n", result.findings.len()));
        for f in &result.findings {
            out.push_str(&format!("  {} @{} {}\n", f.kind.as_str(), f.offset, f.matched));
        }
        out.push_str(&format!("redacted: {}\n", result.redact(text).replace('\n', "\\n")));
    }
    out
}

/// The scanner's observable output has not moved since `main` at `95dbafe7`.
#[test]
fn scanner_output_is_byte_identical_to_the_pre_canonical_baseline() {
    let expected = include_str!("canonical_no_behaviour_change.golden");
    assert_eq!(
        render_report(),
        expected,
        "scanner output diverged from the baseline captured before the canonical model existed"
    );
}

/// Everything the scanner reports survives the trip through the canonical model.
///
/// Kind, offset and label are each recovered from the canonical finding and
/// compared against the scanner finding they came from, so the projection is
/// shown to be lossless over real scanner output — not just over the synthetic
/// `CredentialKind` enumeration the round-trip unit test covers.
#[test]
fn every_scanner_finding_is_recoverable_from_its_canonical_form() {
    let scanner = CredentialScanner::new();
    let mut checked = 0usize;

    for (name, text) in CORPUS {
        let result: ScanResult = scanner.scan(text);
        for finding in &result.findings {
            let canonical = CanonicalFinding::try_from(finding).expect("every scanner finding has a well-formed span");

            assert_eq!(
                canonical.category.to_credential_kind().as_ref(),
                Some(&finding.kind),
                "{name}: {} did not survive the canonical projection",
                finding.kind.as_str()
            );
            assert_eq!(
                canonical.span.start(),
                finding.offset,
                "{name}: span start moved for {}",
                finding.kind.as_str()
            );
            assert_eq!(
                canonical.category.redaction_label(),
                finding.matched,
                "{name}: redaction label changed for {}",
                finding.kind.as_str()
            );
            checked += 1;
        }
    }

    // A corpus that stopped producing findings would pass every assertion above
    // while proving nothing.
    assert!(
        checked >= 40,
        "expected the corpus to exercise many findings, saw {checked}"
    );
}
